import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p53_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor min_reduce_cuda(torch::Tensor x, int64_t dim);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("min_reduce_cuda", &min_reduce_cuda, "Min reduction (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

// Kernel for inner_size > 1: one thread per output element (outer_idx, inner_idx)
// Each thread loops over reduce_size elements
__global__ void min_reduce_outer_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int64_t outer_size,
    int64_t reduce_size,
    int64_t inner_size
) {
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t total = outer_size * inner_size;
    if (idx >= total) return;

    int64_t outer_idx = idx / inner_size;
    int64_t inner_idx = idx % inner_size;

    const float* base = input + outer_idx * reduce_size * inner_size + inner_idx;
    float val = FLT_MAX;
    for (int64_t r = 0; r < reduce_size; r++) {
        float v = base[r * inner_size];
        val = fminf(val, v);
    }
    output[outer_idx * inner_size + inner_idx] = val;
}

// Kernel for inner_size == 1: one block per outer_idx, block reduces over reduce_size
__global__ void min_reduce_inner_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int64_t outer_size,
    int64_t reduce_size
) {
    extern __shared__ float sdata[];
    int64_t outer_idx = blockIdx.x;
    if (outer_idx >= outer_size) return;

    const float* base = input + outer_idx * reduce_size;
    float val = FLT_MAX;
    for (int64_t r = threadIdx.x; r < reduce_size; r += blockDim.x) {
        val = fminf(val, base[r]);
    }
    sdata[threadIdx.x] = val;
    __syncthreads();

    // Block reduction
    for (int s = blockDim.x / 2; s > 32; s >>= 1) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] = fminf(sdata[threadIdx.x], sdata[threadIdx.x + s]);
        }
        __syncthreads();
    }
    // Warp reduction
    if (threadIdx.x < 32) {
        volatile float* vsdata = sdata;
        vsdata[threadIdx.x] = fminf(vsdata[threadIdx.x], vsdata[threadIdx.x + 32]);
        vsdata[threadIdx.x] = fminf(vsdata[threadIdx.x], vsdata[threadIdx.x + 16]);
        vsdata[threadIdx.x] = fminf(vsdata[threadIdx.x], vsdata[threadIdx.x + 8]);
        vsdata[threadIdx.x] = fminf(vsdata[threadIdx.x], vsdata[threadIdx.x + 4]);
        vsdata[threadIdx.x] = fminf(vsdata[threadIdx.x], vsdata[threadIdx.x + 2]);
        vsdata[threadIdx.x] = fminf(vsdata[threadIdx.x], vsdata[threadIdx.x + 1]);
    }
    if (threadIdx.x == 0) {
        output[outer_idx] = sdata[0];
    }
}

torch::Tensor min_reduce_cuda(torch::Tensor x, int64_t dim) {
    int64_t ndim = x.dim();
    // Normalize dim
    if (dim < 0) dim += ndim;

    // Compute outer_size, reduce_size, inner_size
    int64_t outer_size = 1;
    for (int64_t i = 0; i < dim; i++) outer_size *= x.size(i);
    int64_t reduce_size = x.size(dim);
    int64_t inner_size = 1;
    for (int64_t i = dim + 1; i < ndim; i++) inner_size *= x.size(i);

    // Build output shape: input shape with dim removed
    std::vector<int64_t> out_shape;
    for (int64_t i = 0; i < ndim; i++) {
        if (i != dim) out_shape.push_back(x.size(i));
    }
    auto output = torch::empty(out_shape, x.options());

    const float* input_ptr = x.data_ptr<float>();
    float* output_ptr = output.data_ptr<float>();

    if (inner_size == 1) {
        // One block per outer_idx
        int block_size = 256;
        if (reduce_size < 256) block_size = 128;
        dim3 grid(outer_size);
        dim3 block(block_size);
        size_t smem = block_size * sizeof(float);
        min_reduce_inner_kernel<<<grid, block, smem>>>(
            input_ptr, output_ptr, outer_size, reduce_size
        );
    } else {
        // One thread per output element
        int64_t total = outer_size * inner_size;
        int block_size = 256;
        int64_t grid_size = (total + block_size - 1) / block_size;
        min_reduce_outer_kernel<<<grid_size, block_size>>>(
            input_ptr, output_ptr, outer_size, reduce_size, inner_size
        );
    }

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs min reduction over a specific dimension.
        """
    def __init__(self, dim: int):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                Initializes the model with the dimension to reduce over.

                Args:
                    dim (int): The dimension to reduce over.
                """
        self.dim = dim
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Applies min reduction over the specified dimension to the input tensor.

                Args:
                    x (torch.Tensor): Input tensor.

                Returns:
                    torch.Tensor: Output tensor after min reduction over the specified dimension.
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if x.is_cuda and x.dtype == torch.float32 and x.is_contiguous():
            dim = self.dim if self.dim >= 0 else self.dim + x.dim()
            if 0 <= dim < x.dim():
                return _stark_get_extension().min_reduce_cuda(x, dim)
        return torch.min(x, dim=self.dim)[0]
        # <<<END_IMPROVE>>>

